#ifdef VITRAL_WITH_83_NAMES
// Table of the 8.3 names of etc/, generated by scripts/map_to_83.py
#include "java/io/NAMES83.H"

// The folders of a path before etc/ are not in the table (and may contain
// etc/), and after a name that is not in the table there are no more names
// of it
#define FILE_83_UNKNOWN_FOLDER -1
#define FILE_83_OUTSIDE_TABLE -2

/** Index in the table of the child of node named [name, name + length) */
static int
find83Child(int node, const char *name, int length) {
    for ( int i = 0; i < FILE_NAMES_83_COUNT; i++ ) {
        if ( fileNames83Parent[i] == node &&
             strncmp(fileNames83Long[i], name, length) == 0 &&
             fileNames83Long[i][length] == '\0' ) {
            return i;
        }
    }
    return -1;
}

/** Appends [name, name + length) cut to 8.3 as DOS does: up to 8
characters before the first dot and up to 3 after it */
static char *
append83Cut(char *out, const char *name, int length) {
    int i = 0;
    int count = 0;
    for ( ; i < length && name[i] != '.'; i++ ) {
        if ( count < 8 ) {
            *out++ = name[i];
            count++;
        }
    }
    if ( i < length ) {
        *out++ = '.';
        i++;
        for ( count = 0; i < length && name[i] != '.' && count < 3; count++ ) {
            *out++ = name[i++];
        }
    }
    return out;
}

/** Writes in out (with room for 13 characters per name of the path) the
path with 8.3 names, returning the table index of its last name (or a
FILE_83_* value) */
static int
convertTo83(const char *path, char *out) {
    int node = FILE_83_UNKNOWN_FOLDER;
    const int length = (int)strlen(path);
    int start = 0;
    while ( start <= length ) {
        int end = start;
        while ( end < length && path[end] != '/' && path[end] != '\\' ) {
            end++;
        }
        const char *name = path + start;
        const int size = end - start;
        if ( size == 2 && name[0] == '.' && name[1] == '.' ) {
            node = node >= 0 ? fileNames83Parent[node] : FILE_83_UNKNOWN_FOLDER;
            memcpy(out, name, size);
            out += size;
        } else if ( size == 0 || (size == 1 && name[0] == '.') ||
                    memchr(name, ':', size) != NULL ) {
            // Root, drive, current folder or repeated separator
            if ( start == 0 && size != 1 ) {
                node = FILE_83_UNKNOWN_FOLDER;
            }
            memcpy(out, name, size);
            out += size;
        } else {
            int index = -1;
            if ( node != FILE_83_OUTSIDE_TABLE ) {
                index = find83Child(node, name, size);
            }
            if ( index >= 0 ) {
                strcpy(out, fileNames83Short[index]);
                out += strlen(out);
                node = index;
            } else {
                out = append83Cut(out, name, size);
                node = FILE_83_OUTSIDE_TABLE;
            }
        }
        if ( end < length ) {
            *out++ = path[end];
        }
        start = end + 1;
    }
    *out = '\0';
    return node;
}

/** DOS names have any case */
static BOOLEAN
equalsIgnoringCase(const char *a, const char *b) {
    for ( ; *a != '\0' && toupper(*a) == toupper(*b); a++, b++ ) {
    }
    return toupper(*a) == toupper(*b);
}

/** Buffer for convertTo83 */
static char *
new83Buffer(const char *path) {
    return new char[13 * (strlen(path) + 1) + 1];
}
#endif

BOOLEAN
File::isValidPath(const char *rawPath) {
    return rawPath != NULL && rawPath[0] != '\0';
}

BOOLEAN
File::canOpenWithMode(const char *rawPath, const char *mode, int *errorCode) {
    errno = 0;
    FILE *probe = fopen(rawPath, mode);
    if ( probe == NULL ) {
        if ( errorCode != NULL ) {
            *errorCode = errno;
        }
        return FALSE;
    }
    fclose(probe);
    if ( errorCode != NULL ) {
        *errorCode = 0;
    }
    return TRUE;
}

BOOLEAN
File::isDirectoryByReadProbe(const char *rawPath) {
    int openError = 0;
    if ( canOpenWithMode(rawPath, "rb", &openError) ) {
        errno = 0;
        FILE *probe = fopen(rawPath, "rb");
        if ( probe == NULL ) {
            return FALSE;
        }
        unsigned char byteProbe = 0;
        errno = 0;
        const size_t readCount = fread(&byteProbe, 1, 1, probe);
        const BOOLEAN isDirectory = (readCount == 0) && (ferror(probe) != 0) && (errno == EISDIR);
        fclose(probe);
        return isDirectory;
    }

    if ( openError == EISDIR ) {
        return TRUE;
    }

    const size_t pathLength = strlen(rawPath);
    char *slashPath = new char[pathLength + 2];
    memcpy(slashPath, rawPath, pathLength);
    slashPath[pathLength] = '/';
    slashPath[pathLength + 1] = '\0';

    int slashError = 0;
    const BOOLEAN slashOpenOk = canOpenWithMode(slashPath, "rb", &slashError);
    delete[] slashPath;
    if ( slashOpenOk ) {
        return TRUE;
    }
    return slashError == EISDIR || slashError == EACCES || slashError == EPERM;
}

File::File():
    path()
{
}

File::File(const char *path):
    path(path)
{
}

File::File(const String &path):
    path(path)
{
}

String
File::toPlatformName(const String &standardName) {
#ifdef VITRAL_WITH_83_NAMES
    char *converted = new83Buffer(standardName.toCString());
    convertTo83(standardName.toCString(), converted);
    String platformName(converted);
    delete[] converted;
    return platformName;
#else
    return standardName;
#endif
}

File::~File() {
    dispose();
}

void
File::dispose() {
    path.dispose();
}

String
File::getPath() const {
    return path;
}

String
File::getAbsolutePath() const {
    if ( path.length() > 0 && path.charAt(0) == '/' ) {
        return path;
    }
    char buffer[4096];
    if ( getcwd(buffer, sizeof(buffer)) == NULL ) {
        return path;
    }
    String cwd(buffer);
    if ( path.length() == 0 ) {
        return cwd;
    }
    return cwd + "/" + path;
}

String
File::getName() const {
    const int separator = path.indexOf('/');
    if ( separator < 0 ) {
        return path;
    }
    int tailStart = separator + 1;
    int lastSeparator = separator;
    while ( TRUE ) {
        const int nextSeparator = path.indexOf('/', tailStart);
        if ( nextSeparator < 0 ) {
            break;
        }
        lastSeparator = nextSeparator;
        tailStart = nextSeparator + 1;
    }
    return path.substring(lastSeparator + 1);
}

BOOLEAN
File::exists() const {
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return FALSE;
    }

    int readError = 0;
    if ( canOpenWithMode(rawPath, "rb", &readError) ) {
        return TRUE;
    }
    if ( readError == EACCES || readError == EPERM || readError == EISDIR ) {
        return TRUE;
    }
    return isDirectoryByReadProbe(rawPath);
}

BOOLEAN
File::isDirectory() const {
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return FALSE;
    }

    return isDirectoryByReadProbe(rawPath);
}

BOOLEAN
File::isFile() const {
    if ( !exists() ) {
        return FALSE;
    }
    return !isDirectory();
}

BOOLEAN
File::canRead() const {
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return FALSE;
    }
    return canOpenWithMode(rawPath, "rb");
}

BOOLEAN
File::canWrite() const {
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return FALSE;
    }

    return canOpenWithMode(rawPath, "ab");
}

BOOLEAN
File::mkdirs() const {
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return FALSE;
    }

    if ( isDirectoryByReadProbe(rawPath) ) {
        return TRUE;
    }

    const size_t len = strlen(rawPath);
    char *tmp = new char[len + 1];
    memcpy(tmp, rawPath, len + 1);

    for ( size_t i = 1; i < len; i++ ) {
        if ( tmp[i] == '/' ) {
            tmp[i] = '\0';
            mkdir(tmp, 0775);
            tmp[i] = '/';
        }
    }

    errno = 0;
    const BOOLEAN created = (mkdir(tmp, 0775) == 0);
    delete[] tmp;

    return created || isDirectoryByReadProbe(rawPath);
}

ArrayList<String>
File::list() const {
    ArrayList<String> names;
    const String platformPath = toPlatformName(path);
    const char *rawPath = platformPath.toCString();
    if ( !isValidPath(rawPath) ) {
        return names;
    }
#ifdef VITRAL_WITH_83_NAMES
    char *converted = new83Buffer(path.toCString());
    const int folderNode = convertTo83(path.toCString(), converted);
    delete[] converted;
#endif
    // Turbo C++ declares opendir(char *)
    DIR *dir = opendir((char *)rawPath);
    if ( dir == NULL ) {
        return names;
    }
    struct dirent *entry;
    while ( (entry = readdir(dir)) != NULL ) {
        if ( strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0 ) {
            continue;
        }
#ifdef VITRAL_WITH_83_NAMES
        // The names of the table go back to their standard names
        int index = -1;
        if ( folderNode >= 0 ) {
            for ( int i = 0; i < FILE_NAMES_83_COUNT && index < 0; i++ ) {
                if ( fileNames83Parent[i] == folderNode &&
                     equalsIgnoringCase(fileNames83Short[i], entry->d_name) ) {
                    index = i;
                }
            }
        }
        if ( index >= 0 ) {
            names.add(String(fileNames83Long[index]));
            continue;
        }
#endif
        names.add(String(entry->d_name));
    }
    closedir(dir);
    return names;
}

ArrayList<File*>
File::listFiles() const {
    ArrayList<File*> files;
    ArrayList<String> names = list();
    const String base = path;
    const BOOLEAN needsSlash = base.length() > 0 && base.charAt(base.length() - 1) != '/';
    for ( long int i = 0; i < names.size(); i++ ) {
        size_t total = strlen(base.c_str()) + strlen(names[i].c_str()) + 2;
        char *full = new char[total];
        snprintf(full, total, "%s%s%s", base.c_str(), needsSlash ? "/" : "", names[i].c_str());
        files.add(new File(full));
        delete[] full;
    }
    return files;
}

